extends RefCounted
## Sim — the deterministic battle core.
##
## Ghost Company's entire design rests on ONE guarantee:
##   same encounter data + same command list => identical outcome, every time.
## Ghosts are recorded commands replayed against the same sim — nothing else.
##
## RULES (v0 — battle scaffold):
## - Grid is W*H cells. Units occupy integer cells.
## - Commands are data (Dictionary), appended to a recording: {tick, unit_id, type, args}.
## - Ticks are fixed and ordered: deterministic iteration (sorted ids) — NEVER
##   iterate a Dictionary or Node tree unordered.
## - No RNG outside seeded_rand(); no float positions in sim state; no physics.

const TICKS_PER_ROUND: int = 10

var grid_w: int = 8
var grid_h: int = 8
var units: Dictionary = {}        # unit_id -> UnitState (Dictionary)
var commands: Array = []          # the recording: everything the living squad did
var tick: int = 0
var seed_value: int = 0
var log: Array = []               # event log for UI + tests (pure data)

func _init(w: int = 8, h: int = 8, s: int = 0) -> void:
	grid_w = w
	grid_h = h
	seed_value = s

## Deterministic RNG. Only source of randomness in the sim.
func seeded_rand() -> int:
	seed_value = (seed_value * 1103515245 + 12345) & 0x7FFFFFFF
	return seed_value

func add_unit(u: Dictionary) -> void:
	units[u["id"]] = u

func in_bounds(x: int, y: int) -> bool:
	return x >= 0 and y >= 0 and x < grid_w and y < grid_h

func unit_at(x: int, y: int) -> String:
	# Sorted iteration keeps lookup deterministic if multiple exist (should not).
	for id in units.keys().sorted():
		var u: Dictionary = units[id]
		if u["alive"] and u["x"] == x and u["y"] == y:
			return id
	return ""

## Record + apply a command. Command types v0: "move" (args: x,y), "attack" (args: x,y).
func issue_command(unit_id: String, type: String, args: Dictionary) -> void:
	var cmd: Dictionary = {"tick": tick, "unit_id": unit_id, "type": type, "args": args}
	commands.append(cmd)
	_apply(cmd)

func _apply(cmd: Dictionary) -> void:
	var u: Dictionary = units.get(cmd["unit_id"], {})
	if u.is_empty() or not u["alive"]:
		return
	if cmd["type"] == "move":
		var nx: int = int(cmd["args"].get("x", u["x"]))
		var ny: int = int(cmd["args"].get("y", u["y"]))
		if in_bounds(nx, ny) and unit_at(nx, ny) == "":
			u["x"] = nx
			u["y"] = ny
			log.append({"tick": tick, "event": "move", "unit": u["id"], "to": [nx, ny]})
	elif cmd["type"] == "attack":
		var tx: int = int(cmd["args"].get("x", u["x"]))
		var ty: int = int(cmd["args"].get("y", u["y"]))
		var target_id: String = unit_at(tx, ty)
		if target_id != "":
			var t: Dictionary = units[target_id]
			t["hp"] = int(t["hp"]) - int(u["atk"])
			if t["hp"] <= 0:
				t["alive"] = false
				log.append({"tick": tick, "event": "death", "unit": target_id, "by": u["id"]})
			else:
				log.append({"tick": tick, "event": "hit", "unit": target_id, "by": u["id"], "hp": t["hp"]})

## Replay a recorded command list against THIS state (ghost replay = same code path).
## A ghost either matches its recording or the test fails — by design there is
## no other possible behavior.
func replay(recording: Array) -> void:
	for cmd in recording:
		_apply(cmd)

## State hash for determinism tests: run twice, hashes MUST match.
func state_hash() -> int:
	var h: int = 2166136261
	for id in units.keys().sorted():
		var u: Dictionary = units[id]
		for v in [u["x"], u["y"], int(u["hp"]), int(u["alive"])]:
			h = (h ^ int(v)) * 16777619
	h = (h ^ tick) * 16777619
	return h & 0x7FFFFFFF
